/// <reference types="@rbxts/compiler-types" />
import { GroupMotor, SingleMotor } from "@rbxts/flipper";
export type GroupMotorValue = {
    [key: string]: number;
};
export type MapValues<T extends GroupMotorValue, U> = {
    [K in keyof T]: U;
};
export interface MotorState {
    complete: boolean;
    value: number;
    velocity?: number;
}
/**
 * Gets the internal state of the motor.
 * @param motor The motor to get the state of
 * @returns The motor's state
 */
export declare function motorGetState(motor: SingleMotor): MotorState;
/**
 * Sets the internal state of the motor.
 * @param motor The motor to set the value of
 * @param state The state to set
 */
export declare function motorSetState(motor: SingleMotor, state: Partial<MotorState>): void;
/**
 * Applies an impulse to the motor's velocity.
 * @param motor The motor to apply the impulse to
 * @param impulse The impulse to apply
 */
export declare function motorImpulse(motor: SingleMotor, impulse: number): void;
/**
 * Gets the state of every key in the group motor.
 * @param motor The group motor to get the state of
 * @returns The group motor's state
 */
export declare function groupMotorGetState<T extends GroupMotorValue>(groupMotor: GroupMotor<T>): MapValues<T, MotorState>;
/**
 * Sets the state with the given keys in the group motor.
 * @param motor The group motor to set the state of
 * @param state The state to set
 */
export declare function groupMotorSetState<T extends GroupMotorValue>(groupMotor: GroupMotor<T>, states: Partial<MapValues<T, Partial<MotorState>>>): void;
/**
 * Applies impulses to the motor's velocity.
 * @param motor The group motor to apply the impulses to
 * @param impulses The impulses to apply
 */
export declare function groupMotorImpulse<T extends GroupMotorValue>(groupMotor: GroupMotor<T>, impulses: {
    [K in keyof T]?: number;
}): void;
